mapper.select:
select * from  Sys_Filed_Change_Record where  Fcr_Id in (
    select a.Fcr_Id from (
     select
         first_value(Fcr_Id) as Fcr_Id,
         max(Fcr_Update_Time) as fcrUpdateTime
     from Sys_Filed_Change_Record  where  Fcr_Key=#{fcrKey}
     group by Fcr_Filed
   ) a
)
